using Monergy.Platform;
using Monergy.Services.CustomerIdentity.Application;
namespace Monergy.Services.CustomerIdentity.Infrastructure;

// Explicit test adapter. Runtime always uses the tenant-database owner adapter.
public sealed class InMemoryCustomerAdministration(IEnumerable<AdminCustomer> seed):ICustomerAdministrationRepository
{
 private readonly object sync=new();
 private readonly Dictionary<(string,string),AdminCustomer> customers=seed.ToDictionary(x=>(x.TenantId,x.CustomerId));
 private readonly Dictionary<(string,string),CustomerStatusReceipt> receipts=[];
 public Task<AdminCustomerPage> ListAsync(string tenant,AdminCustomerQuery query,CancellationToken ct)
 {ct.ThrowIfCancellationRequested();CustomerAdministration.Query(query);lock(sync){var all=customers.Values.Where(x=>x.TenantId==tenant).ToArray();var filtered=all.Where(x=>(query.Status=="all"||x.Active==(query.Status=="active"))&&string.Join(" ",x.DisplayName,x.Email,x.SecondaryLabel,x.CustomerId).Contains(query.Search,StringComparison.OrdinalIgnoreCase)).ToArray();var page=filtered.Where(x=>query.After is null||StringComparer.Ordinal.Compare(x.CustomerId,query.After)>0).OrderBy(x=>x.CustomerId,StringComparer.Ordinal).Take(51).ToArray();return Task.FromResult(new AdminCustomerPage(tenant,page.Take(50).ToArray(),page.Length>50?page[49].CustomerId:null,all.Length,all.Count(x=>x.Active),all.Count(x=>!x.Active),filtered.Length));}}
 public Task<AdminCustomer?> ReadAsync(string tenant,string customer,CancellationToken ct){ct.ThrowIfCancellationRequested();lock(sync)return Task.FromResult(customers.GetValueOrDefault((tenant,customer)));}
 public Task<CustomerStatusReceipt> ChangeAsync(string tenant,string actor,string customer,CustomerStatusChange change,DateTimeOffset now,CancellationToken ct)
 {ct.ThrowIfCancellationRequested();CustomerAdministration.Change(change);lock(sync){if(receipts.TryGetValue((tenant,change.OperationId),out var prior)){if(prior.RecordedBy!=actor||prior.CustomerId!=customer||prior.Before.Version!=change.ExpectedVersion||prior.After.Active!=change.Active||prior.Reason!=change.Reason)throw new TenantBoundaryException("CUSTOMER_OPERATION_CONFLICT",409);return Task.FromResult(prior);}var before=customers.GetValueOrDefault((tenant,customer))??throw new TenantBoundaryException("CUSTOMER_NOT_FOUND",404);if(before.Version!=change.ExpectedVersion)throw new TenantBoundaryException("CUSTOMER_VERSION_CONFLICT",409);if(before.Active==change.Active)throw new TenantBoundaryException("CUSTOMER_STATUS_UNCHANGED",409);if(change.Active&&!before.ActivationAvailable)throw new TenantBoundaryException("CUSTOMER_ACTIVATION_UNAVAILABLE",409);var after=before with{Active=change.Active,Version=checked(before.Version+1)};var receipt=new CustomerStatusReceipt(tenant,customer,change.OperationId,before,after,change.Reason,actor,"Organization administrator",now);receipts.Add((tenant,change.OperationId),receipt);customers[(tenant,customer)]=after;return Task.FromResult(receipt);}}
 public Task<CustomerStatusReceipt?> ReceiptAsync(string tenant,string customer,string operation,CancellationToken ct){ct.ThrowIfCancellationRequested();lock(sync)return Task.FromResult(receipts.Values.SingleOrDefault(x=>x.TenantId==tenant&&x.CustomerId==customer&&x.OperationId==operation));}
 public Task<CustomerStatusHistory> HistoryAsync(string tenant,string customer,long? before,CancellationToken ct){ct.ThrowIfCancellationRequested();lock(sync){if(!customers.ContainsKey((tenant,customer)))throw new TenantBoundaryException("CUSTOMER_NOT_FOUND",404);var page=receipts.Values.Where(x=>x.TenantId==tenant&&x.CustomerId==customer&&(before is null||x.After.Version<before)).OrderByDescending(x=>x.After.Version).Take(51).ToArray();return Task.FromResult(new CustomerStatusHistory(tenant,customer,page.Take(50).ToArray(),page.Length>50?page[49].After.Version:null));}}
}
